for(const [id,d]of Object.entries(DISCOVERIES)){d.branch=id==='agriculture'?'environment':id==='lifeSupport'?'bioengineering':'mechanical';d.facility=RESEARCH_BRANCHES[d.branch].facility;d.cost=Object.fromEntries(Object.entries(d.cost).map(([k,v])=>[k,v*4]));d.work*=12;}
const paths={magic:[['arcanePractice','Dasar arkanum'],['runeCraft','Rekayasa rune'],['arcaneIndustry','Industri mana']],mechanical:[['wheelcraft','Roda dan transportasi'],['precisionEngineering','Rekayasa presisi'],['automation','Otomasi']],biotic:[['physiology','Fisiologi adaptif'],['symbiosis','Simbiosis'],['bioMobility','Mobilitas biotik']],bioengineering:[['herbalMedicine','Pengobatan hayati'],['genetics','Rekayasa gen'],['regenerativeMedicine','Pengobatan regeneratif']],mental:[['mindfulness','Disiplin mental'],['cognitiveScience','Ilmu kognitif'],['neuralLink','Jejaring pikiran']],environment:[['forestry','Pengelolaan hutan'],['soilScience','Ilmu tanah'],['closedEcology','Ekologi tertutup']],warfare:[['weaponry','Persenjataan'],['ballistics','Balistik'],['militaryLogistics','Logistik militer']],social:[['cooperationScience','Ilmu kerja sama'],['educationScience','Ilmu pendidikan'],['publicHealth','Kesehatan masyarakat']],diplomatic:[['linguistics','Linguistik'],['negotiation','Negosiasi'],['interplanetaryProtocol','Protokol antarplanet']],government:[['administration','Administrasi'],['institutions','Lembaga publik'],['federalSystems','Sistem federasi']]};
for(const [branch,path]of Object.entries(paths))for(const [i,[id,name]]of path.entries()){const requires=i?[path[i-1][0],...(i===1?['metallurgy']:[])]:branch==='magic'?[]:['agriculture'];DISCOVERIES[id]={name,branch,facility:RESEARCH_BRANCHES[branch].facility,requires,tech:branch==='magic'&&i===0?40:30+i*140,skill:8+i*25,stage:Math.min(3,i+1),work:120+i*120,cost:{wood:60+i*30,stone:35+i*20,food:30+i*20,...(i?{metal:20*i}:{}),...(i===2?{energy:25}: {})}};}
DISCOVERIES.arcanePractice.skill=20;DISCOVERIES.arcanePractice.needs=s=>!!s._context?.root.world.sources.some(o=>o.planet===s._context.civ.planet&&Math.hypot(o.x-s._context.civ.x,o.y-s._context.civ.y)<320)&&s.agents.some(a=>a.alive&&!a.away&&a.arcaneSensitivity>=75);
DISCOVERIES.wheelcraft.requires=['metallurgy'];DISCOVERIES.precisionEngineering.requires=['wheelcraft','mechanics'];DISCOVERIES.automation.requires=['precisionEngineering','electronics'];DISCOVERIES.neuralLink.requires=['cognitiveScience','electronics'];DISCOVERIES.ballistics.requires=['weaponry','mechanics'];DISCOVERIES.interplanetaryProtocol.requires=['negotiation','electronics'];DISCOVERIES.lifeSupport.requires.push('regenerativeMedicine','closedEcology');
for(const key of ['travel','explore','mineOre','forgeWeapon','makeVehicle','treat','restore','meditate','govern'])ACTIONS.push(key);
